import {VERSION,HEROES,SCENES,DIFFICULTIES,CELLS,random,rollScene,rollDifficulty,createRun,destinations,generateScene,createBattle,stepBattle,settleBattle,applyReward,useMed} from './zr-engine.mjs';
import {paintScene,heroPreview,prop,person} from './zr-render.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tab='assets',run=null,battle=null,effects=[],time=0,last=0,speed=1,paused=false,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,options=[],revealed=false,prior=null,log=[],shake=0;
const sourceAssets=await fetch('/zr-assets.json').then(r=>{if(!r.ok)throw Error('Asset catalog unavailable');return r.json()});
const assets=[...sourceAssets,...HEROES.map(h=>({id:h.id,name:h.name+' · '+h.role,category:'Survivors',status:'In game · 2D',kind:'hero',hero:h,company:h.weapon.split(' ')[0],description:h.weapon+' / '+h.armor+'. '+h.special+': '+h.detail})),...HEROES.flatMap(h=>[{id:h.id+'-weapon',name:h.weapon,category:'Weapons',status:'In game · 2D',kind:'weapon',hero:h,company:h.weapon.split(' ')[0],description:`${h.damage} base damage · ${h.range} range units · ${h.rate}s attack interval. Equipped by ${h.name}.`},{id:h.id+'-armor',name:h.armor,category:'Armor',status:'In game · 2D',kind:'armor',hero:h,company:h.armor.split(' ')[0],description:`${h.def} damage reduction per hit. Equipped by ${h.name}.` }]),...SCENES.map(s=>({id:s.id,name:s.name,category:'Scene generators',kind:'scene',status:'In game · 2D',scene:s,company:'Zombie Run',description:s.desc+' Shared generator used by previews and combat; decorative props do not yet block bullets.'})),...['Walker','Brute'].map((name,i)=>({id:'enemy'+i,name,category:'Zombies',kind:'enemy',status:'In game · 2D',company:'High-school outbreak',description:i?'105 HP, 5 armor, slow heavy melee.':'48–72 HP, low armor, melee pursuit. Waves arrive from the high school; proximity, damage threat and taunts determine targets.'})),...['Medkit','Marked scrap','Pumpkin lantern'].map((name,i)=>({id:'utility'+i,name,category:'Supplies & effects',kind:'utility',status:'In game · 2D',company:'Mercy / Torque',description:['Restores 35 HP to one living wounded survivor. Consumed, never free round healing.','Collected on surviving a scene. Three scrap repairs the milestone vehicle.','2D soft glow; cosmetic Halloween lighting, not a threat indicator.'][i]}))];
for(const cat of [...new Set(assets.map(a=>a.category))].sort())$('category').add(new Option(cat));
function preview(canvas,a){if(a.kind==='hero')heroPreview(canvas,a.hero);else if(a.kind==='scene'){const scene=generateScene(a.id,1,41);paintScene(canvas,scene,createBattle(createRun(),scene));}else{const c=canvas.getContext('2d');c.fillStyle='#233842';c.fillRect(0,0,canvas.width,canvas.height);c.save();c.translate(canvas.width/2,canvas.height/2);c.scale(2,2);if(a.kind==='enemy')person(c,{x:0,y:10,hp:100,maxHp:100,side:'enemy',color:a.id==='enemy1'?'#ba91a2':'#a9ba82'},0,false);else if(a.kind==='weapon'&&a.hero.range<60){c.strokeStyle='#ab8869';c.lineWidth=6;c.beginPath();c.moveTo(0,28);c.lineTo(0,-22);c.stroke();c.fillStyle='#bdc8bd';if(a.hero.id==='mara')c.fillRect(-22,-30,44,17);else if(a.hero.id==='rosa'){c.fillStyle='#687f90';c.fillRect(-6,-30,12,45);}else{c.beginPath();c.moveTo(-4,8);c.lineTo(-5,-18);c.lineTo(5,-36);c.lineTo(6,8);c.fill();}}else if(a.kind==='weapon'){c.strokeStyle='#ccb482';c.lineWidth=6;c.beginPath();c.moveTo(-45,0);c.lineTo(35,0);c.stroke();c.fillStyle='#667e8a';c.fillRect(-12,-8,24,13);c.fillRect(30,-3,20,6);c.fillStyle='#a27556';c.fillRect(-42,0,22,9);}else if(a.kind==='armor'){c.fillStyle=a.hero.color;c.beginPath();c.moveTo(-18,-28);c.lineTo(-30,-12);c.lineTo(-20,-6);c.lineTo(-20,28);c.lineTo(20,28);c.lineTo(20,-6);c.lineTo(30,-12);c.lineTo(18,-28);c.lineTo(7,-18);c.lineTo(-7,-18);c.fill();c.strokeStyle='#e2e2c1';c.strokeRect(-13,-7,26,25);}else prop(c,{x:0,y:0,w:35,h:30,kind:a.id==='utility2'?'pumpkin':'crate'});c.restore();}}
function renderAssets(){const query=$('search').value.toLowerCase();const filtered=assets.filter(a=>($('category').value==='All'||a.category===$('category').value)&&($('status').value==='All'||a.status===$('status').value)&&[a.name,a.company,a.category,a.description].join(' ').toLowerCase().includes(query)).sort((a,b)=>a[$('sort').value].localeCompare(b[$('sort').value])||a.name.localeCompare(b.name));$('count').textContent=`${filtered.length} / ${assets.length} assets`;$('grid').replaceChildren();for(const a of filtered){const btn=document.createElement('button');btn.className='asset';btn.setAttribute('aria-label','Inspect '+a.name);btn.innerHTML=(a.preview?`<img loading="lazy" src="${a.preview}" alt="${esc(a.name)} rendered source preview">`:'<canvas width="320" height="237" aria-label="2D game asset preview"></canvas>')+`<div class="meta"><strong>${esc(a.name)}</strong><small>${esc(a.category)} · ${esc(a.company)}</small><span class="badge">${esc(a.status)}</span></div>`;if(!a.preview)preview(btn.querySelector('canvas'),a);btn.onclick=()=>detail(a);$('grid').append(btn);}}
function detail(a){$('detail').innerHTML=`<h2>${esc(a.name)}</h2>${a.preview?`<img src="${a.preview}" alt="${esc(a.name)}">`:'<canvas width="600" height="350"></canvas>'}<p>${esc(a.description)}</p>${a.kind==='scene'?'<p class="muted">Static inspection of the actual generated recipe. Shows the initial wave; later reinforcements appear during play.</p>':''}<p class="notice">${esc(a.status)}${a.kind==='model'?' · Static rendered preview. Source GLB is not yet a skinned or animated game asset.':''}</p>${a.dimensions?`<p>Metres: ${a.dimensions.map(n=>n.toFixed(2)).join(' × ')}</p>`:''}${a.glb?`<a href="${a.glb}" download>Download source GLB</a>`:''}${a.kind==='scene'?'<label>Preview difficulty<select id="preview-diff">'+DIFFICULTIES.map((x,i)=>`<option value="${i}" ${i===1?'selected':''}>${x}</option>`).join('')+'</select></label>':''}`;if(!a.preview)preview($('detail').querySelector('canvas'),a);if(a.kind==='scene')$('preview-diff').onchange=()=>{const scene=generateScene(a.id,+$('preview-diff').value,41);paintScene($('detail').querySelector('canvas'),scene,createBattle(createRun(),scene));};$('asset-dialog').showModal();}
$('close-detail').onclick=()=>$('asset-dialog').close();for(const id of ['search','category','status','sort'])$(id).addEventListener(id==='search'?'input':'change',renderAssets);
function switchTab(t){tab=t;for(const id of ['assets','play','direction'])$(id).hidden=id!==t;$('filters').hidden=t!=='assets';document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===t));if(t==='play'){panel();draw();}history.replaceState(null,'','#'+t);}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('launch').onclick=()=>switchTab('play');
$('direction').innerHTML=`<div class="plan-grid"><article class="plan-card"><h2>Production path</h2><p><b>Working v${VERSION}:</b> seeded 2D scenes, team selection, ten roles, five-person cap, school-origin waves, threat/taunt targeting, party stances, range/cooldowns, aggro, armor, crits/headshots, automatic specials, persistent HP, consumed medicine, scrap, vehicle milestone, lasting rewards and local saves.</p><p><b>Foundation, not finished production:</b> needs longer balance/playtesting, tactical navigation and cover, final character art/animation, audio, and assistive nonvisual gameplay. No online accounts or multiplayer here.</p></article><article class="plan-card"><h2>Halloween materials</h2><p><b>Now:</b> actual Canvas 2D moonlit color wash, pumpkin glow, soft edge mist, shadows, and event-driven effects.</p><p><b>Planned shaders:</b> emissive candle flicker with restrained bloom; blue-violet rim light; wet roughness highlights; translucent ghosts; purple rune trails. These are art targets, not implemented GPU shaders or new supernatural mechanics.</p></article><article class="plan-card"><h2>HUD & feedback</h2><p>One compact navigation bar. Fixed party HP, fictional clock, destination, consumables and active intent. Scene cards live in a bounded panel. Damage numbers supplement bars; headshot, crit, heal, shield and death feedback comes from actual combat events.</p><p>Pause, 1×/2× speed, retreat, and shake-off. No automatic camera reframing. Downed members stay down for this run; no end-round health refill.</p></article><article class="plan-card"><h2>Assets & remaster</h2><p>All ${assets.length} registered entries appear in Assets: 50 reviewed gear models, SUV, ten roles with weapons/armor, ten shared scene generators, zombies and utilities. Status labels distinguish game drawings from reviewed source models.</p><p>Optional Meshy remaster must retain scale, pivots, collision footprints, interaction anchors and animation contracts. No Meshy generation started. The current characters use readable procedural sprites; final bespoke art remains planned. Weapons and armor previews are schematic, not final unique model silhouettes.</p></article><article class="plan-card"><h2>Release gates</h2><p>Replay tests, HP persistence, deterministic aggro, no duplicate kill rewards, compatible scene rolls, desktop/phone checks, asset load checks and measured run duration. Next: accessibility, audio mixing, navigation/cover tests and wider seeded difficulty sweeps.</p><p>School to home is 500 m of route travel. Each intimate encounter shows a small portion of that segment. Level 0 ends at 18:00; this is a tutorial daylight limit, not the full game's nuclear countdown.</p></article><article class="plan-card"><h2>Research review</h2><p id="review-note">Reviewed by Evan’s PC against PLAYBOOK studies, not the unconnected Game Oracle. Critique: too many systems; prove loadout agency, visible intent and fair risk first. Incorporated stance choices, explicit costs, retreat, shared scene recipes, and persistent health. Full five-minute usability testing remains pending.</p><p>Inventory compatibility from Thunder Tier One, constrained scavenging from Overland, visible intent from Shadow Tactics and persistent readiness from Plants vs. Zombies inform the design. Their full rulesets are not copied.</p></article></div>`;
function save(){try{if(run)localStorage.setItem('zombie-run-v1',JSON.stringify(run));}catch{}}
try{const saved=JSON.parse(localStorage.getItem('zombie-run-v1'));if(saved?.schema===1&&Array.isArray(saved.party)&&saved.party.length<=5){run=saved;if(['combat','cards'].includes(run.phase)){run.phase='route';run.q=run.previous?.q??Math.max(0,run.q-1);run.r=run.previous?.r??0;}}}catch{}
const clock=()=>`${String(Math.floor(run.minutes/60)).padStart(2,'0')}:${String(run.minutes%60).padStart(2,'0')}`;
function button(text,fn,disabled=false){const b=document.createElement('button');b.innerHTML=text;b.disabled=disabled;b.onclick=fn;$('game-panel').append(b);return b;}
function statusHead(title){$('game-panel').innerHTML=`<h2>${title}</h2><p>${clock()} · ${run.q*100}/500 m<br>${run.supplies.scrap} scrap · ${run.supplies.med} medkits · ${run.car?'SUV repaired':'On foot'}</p>`;}
function panel(){if(tab!=='play')return;$('game-panel').replaceChildren();if(!run){$('game-panel').innerHTML='<h2>School → home</h2><p>500 metres. Five steps. Choose Evan and up to four friends. Survivors fight automatically; wounds persist.</p><p class="muted">This is a playable foundation. Equipment is role-based, with a starting kit choice below.</p>';for(const h of HEROES){const row=document.createElement('div');row.className='hero-choice';row.innerHTML=`<input type="checkbox" id="pick-${h.id}" ${['evan','mara','jules'].includes(h.id)?'checked':''} ${h.id==='evan'?'disabled':''}><label for="pick-${h.id}">${h.name} · ${h.role}</label>`;$('game-panel').append(row);}const l=document.createElement('label');l.innerHTML='Starting kit<select id="kit"><option value="balanced">Balanced · standard role gear</option><option value="armored">Armored · +2 armor, −10% speed</option><option value="light">Light · +15% speed, −1 armor</option></select>';$('game-panel').append(l);button('Begin run →',()=>{const ids=HEROES.filter(h=>$('pick-'+h.id).checked).map(h=>h.id);if(ids.length>5){alert('Choose Evan and at most four friends.');return;}const kit=$('kit').value;run=createRun(ids,Date.now()>>>0);for(const h of run.party){if(kit==='armored'){h.def+=2;h.speed*=.9;}if(kit==='light'){h.speed*=1.15;h.def=Math.max(0,h.def-1);}}save();panel();draw();});return;}
statusHead({route:'Choose your next hex',cards:'Choose your encounter',combat:'Hold the school approach',reward:'You survived. Choose.',milestone:'Midpoint · the garage',won:'You made it home.',lost:'The run is over.',retreated:'Regroup'}[run.phase]||'Journey');
if(run.phase==='route'){const choices=destinations(run);if(!choices.length){button('Return to school',reset);return;}$('game-panel').insertAdjacentHTML('beforeend','<p>Move toward home. At 300 m, stop at the garage. Green map buttons mark reachable hexes.</p>');for(const c of choices)button(`Advance ${c.q*100} m · ${c.r===0?'middle':c.r<0?'upper':'lower'} route`,()=>chooseCell(c));button('Use medkit · heal most wounded +35 HP',()=>{useMed(run);save();panel();},!run.supplies.med||!run.party.some(h=>h.hp>0&&h.hp<h.maxHp));}
else if(run.phase==='cards'){const box=document.createElement('div');box.className='inline';box.innerHTML='<button id="type-mode">Choose place</button><button id="risk-mode">Choose risk</button>';$('game-panel').append(box);$('type-mode').onclick=()=>makeOptions('scene');$('risk-mode').onclick=()=>makeOptions('risk');$('game-panel').insertAdjacentHTML('beforeend',`<p class="muted">${run.mode==='scene'?'You pick the place. Threat density is rolled.':'You pick the threat level. A compatible place is rolled.'}</p>`);const stance=document.createElement('label');stance.innerHTML='Party stance<select id="stance"><option value="guard">Protect Evan · frontline +3 armor, −10% damage</option><option value="balanced">Balanced · standard stats</option><option value="press">Press · +20% damage, −2 armor</option></select>';$('game-panel').append(stance);$('stance').value=run.stance||'guard';run.stance=$('stance').value;$('stance').onchange=()=>run.stance=$('stance').value;$('game-panel').insertAdjacentHTML('beforeend','<p class="muted">Random risk: 40% Quiet · 35% Tense · 19% Dangerous · 6% Brutal. Brutal can kill the party. Scout before committing, or retreat during combat.</p>');for(const o of options)button(`<strong>${run.mode==='scene'?o.scene.name:DIFFICULTIES[o.difficulty]}</strong><small>${revealed?o.scene.name+' · '+DIFFICULTIES[o.difficulty]:run.mode==='scene'?(o.scene.safe?'Safe · no zombies':'Risk hidden · may be Brutal'):'Place concealed'} · ${o.scene.safe&&revealed?'search': 'encounter'}</small>`,()=>enter(o)).className='choice';button(`Scout choices · ${run.scouts} use left`,()=>{run.scouts--;revealed=true;panel();save();},!run.scouts||revealed);}
else if(run.phase==='combat'){const alive=battle?.enemies.filter(e=>e.hp>0&&e.active).length||0;const pending=battle?.enemies.filter(e=>!e.active).length||0;$('game-panel').insertAdjacentHTML('beforeend',`<p>${esc(battle.scene.type.name)} · ${DIFFICULTIES[battle.scene.difficulty]}</p><p id="combat-count">${alive} active · ${pending} arriving</p><p class="muted">School waves arrive every 5s. Frontline proximity draws aggro; damage builds threat. Rosa can taunt. Evan holds the rear, but is not invulnerable.</p>`);button(paused?'Resume':'Pause',()=>{paused=!paused;panel();});button(speed===1?'Speed · 1×':'Speed · 2×',()=>{speed=speed===1?2:1;panel();});button(reduced?'Shake · off':'Shake · on',()=>{reduced=!reduced;panel();});button('Retreat · retain wounds, lose 30 minutes',()=>{if(!battle)return;finish(true);});$('game-panel').insertAdjacentHTML('beforeend','<div id="combat-log"></div>');}
else if(['reward','milestone','retreated'].includes(run.phase)){const milestone=run.phase==='milestone';if(run.phase==='retreated')$('game-panel').insertAdjacentHTML('beforeend','<p>Your party fell back. Wounds persist. Take supplies and try another approach.</p>');if(milestone){$('game-panel').insertAdjacentHTML('beforeend','<p>Spend your salvage to change the rest of the journey.</p>');button('Repair SUV · 3 scrap · travel costs 25 instead of 40 minutes',()=>reward('car'),run.supplies.scrap<3);button('Rescue a companion · joins with their own kit',()=>reward('recruit'),run.party.length>=5);}button('Sharpen the team · +5 attack damage to living members',()=>reward('damage'));button('Reinforce armor · +2 damage reduction to living members',()=>reward('armor'));button('Take medical supplies · +2 medkits (no automatic healing)',()=>reward('med'));}
else{$('game-panel').insertAdjacentHTML('beforeend',`<p>${run.phase==='won'?'Your surviving party reached home.':'Your party was defeated or ran out of daylight.'} ${run.party.filter(h=>h.hp>0).length}/${run.party.length} survived.</p><p>${run.history.length} encounters · ${run.minutes-360} fictional minutes</p>`);button('New run',reset);}
if(run.phase!=='combat')button('Restart run…',()=>{if(confirm('Start over? This replaces the saved run on this device.'))reset();});renderParty();}
function reset(){run=null;battle=null;localStorage.removeItem('zombie-run-v1');$('party').replaceChildren();panel();draw();}
function chooseCell(c){prior={q:run.q,r:run.r};run.previous=prior;run.pending=c;run.phase='cards';makeOptions('scene');}
function makeOptions(mode){run.mode=mode;const rng=random(run.seed+run.encounter*197+run.pending.q*37);options=[];if(mode==='scene'){const list=[...SCENES];for(let i=0;i<3;i++){const candidate=rollScene(rng);let s=list.find(x=>x.id===candidate.id)||list[0];list.splice(list.indexOf(s),1);options.push({scene:s,difficulty:s.safe?0:rollDifficulty(rng)});}}else for(const difficulty of [0,1,2,3])options.push({scene:rollScene(rng,true),difficulty});revealed=false;panel();draw();}
function enter(o){run.q=run.pending.q;run.r=run.pending.r;run.phase='combat';run.visited.push(run.q+','+run.r);accumulator=0;battle=createBattle(run,generateScene(o.scene.id,o.difficulty,run.seed+run.encounter*13));effects=[];log=[];paused=false;time=0;save();panel();draw();if(battle.done)finish();}
function finish(retreat=false){if(!battle)return;if(retreat)battle.won=false;settleBattle(run,battle);if(!battle.won&&run.phase!=='lost'){run.q=run.previous.q;run.r=run.previous.r;run.minutes+=30;}battle=null;effects=[];save();panel();draw();}
function reward(kind){if(applyReward(run,kind)){save();panel();draw();}}
function renderParty(){if(!run)return;$('party').innerHTML=run.party.map(h=>{const a=battle?.allies.find(a=>a.id===h.id)||h;return `<div class="member"><strong>${esc(h.name)} <small style="display:inline">Lv ${h.level}</small></strong><div class="bar" role="meter" aria-label="${h.name} health" aria-valuemin="0" aria-valuemax="${h.maxHp}" aria-valuenow="${Math.ceil(a.hp)}"><i style="width:${a.hp/h.maxHp*100}%"></i></div><small>${Math.ceil(a.hp)}/${h.maxHp} HP · ${a.hp<=0?'DOWN':a.intent||h.role}</small><small>${esc(h.weapon)}</small><small>${esc(h.special)} · ${battle?Math.ceil(a.specialCool||0)+'s': 'automatic'}</small></div>`;}).join('');}
function mapPoint(c){return {x:165+c.q*112,y:280+c.r*126+(c.q%2)*63};}
function drawMap(){const canvas=$('world'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,900,560);ctx.fillStyle='#17232d';ctx.fillRect(0,0,900,560);for(const c of CELLS){const p=mapPoint(c),seen=run?.visited.includes(c.q+','+c.r);ctx.beginPath();for(let i=0;i<6;i++){const a=Math.PI/3*i;const x=p.x+71*Math.cos(a),y=p.y+71*Math.sin(a);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.fillStyle=seen?'#486256':'#273c45';ctx.fill();ctx.strokeStyle=c.q===3&&c.r===0?'#d5a86a':'#52696e';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#d7e3d6';ctx.font='15px Manrope,sans-serif';ctx.textAlign='center';const name=c.q===0&&c.r===0?'SCHOOL':c.q===5&&c.r===0?'HOME':c.q===3&&c.r===0?'GARAGE':seen?'Cleared':'?';ctx.fillText(name,p.x,p.y);if(run?.q===c.q&&run.r===c.r){ctx.fillStyle='#b1e8c7';ctx.beginPath();ctx.arc(p.x,p.y+23,8,0,7);ctx.fill();}}ctx.textAlign='start';ctx.fillStyle='#b6c8c6';ctx.font='15px sans-serif';ctx.fillText('School waves follow your journey. Reach home before 18:00.',125,525);}
function draw(){if(tab!=='play')return;$('map-buttons').replaceChildren();if(battle){paintScene($('world'),battle.scene,battle,effects,time,reduced?0:shake);$('stage-caption').textContent='Automatic encounter · health persists · school waves approach from the left';}else{drawMap();$('stage-caption').textContent='100 m per route step · intimate encounter scenes · local save';if(run?.phase==='route'){const rect=$('world').getBoundingClientRect(),scale=Math.min(rect.width/900,rect.height/560),ox=(rect.width-900*scale)/2,oy=(rect.height-560*scale)/2;for(const cell of destinations(run)){const p=mapPoint(cell),b=document.createElement('button');b.textContent='Go →';b.setAttribute('aria-label',`Move to ${cell.q*100} metres row ${cell.r}`);b.style.left=(ox+p.x*scale)+'px';b.style.top=(oy+(p.y+25)*scale)+'px';b.onclick=()=>chooseCell(cell);$('map-buttons').append(b);}}}}
let accumulator=0;let hud=0;function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(battle&&tab==='play'&&!paused){accumulator+=dt*speed;while(accumulator>=.05&&!battle.done){accumulator-=.05;stepBattle(battle,.05);time=battle.time;for(const e of battle.events){effects.push({...e,at:time});if(['crit','headshot','special'].includes(e.type))shake=Math.max(shake,e.type==='headshot'?4:2);if(['headshot','heal','kill','special'].includes(e.type))log.unshift(e.type==='kill'?`${e.target} down`:e.type==='headshot'?`${e.name}: HEADSHOT`:`${e.name} · ${e.type} ${e.amount||''}`);}}effects=effects.filter(e=>time-e.at<1.1);shake*=Math.exp(-dt*12);if(battle.done){finish();}else{draw();hud+=dt;if(hud>.2){hud=0;renderParty();if($('combat-count'))$('combat-count').textContent=`${battle.enemies.filter(e=>e.active&&e.hp>0).length} active · ${battle.enemies.filter(e=>!e.active).length} arriving`;if($('combat-log'))$('combat-log').innerHTML=log.slice(0,4).map(s=>'<div class="log">'+esc(s)+'</div>').join('');}}}requestAnimationFrame(frame);}requestAnimationFrame(frame);window.addEventListener('resize',draw);renderAssets();switchTab(['play','direction'].includes(location.hash.slice(1))?location.hash.slice(1):'assets');
